const J=globalThis.window?.jarvis;
if(J&&(new URLSearchParams(location.search).get('view')||'main')==='main'){
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let panel,state,masked=false,previous,mode='menu',tabId,opening=false,rows=[],selected=0;
 const notice=m=>{const e=document.createElement('p');e.className='wb-notice';e.textContent=m;document.body.append(e);setTimeout(()=>e.remove(),4500);};
 async function close(){panel?.remove();panel=null;if(masked)await J.call('tabs-show',true).catch(()=>{});masked=false;previous?.focus?.();}
 const tools=[['Meeting work','Transcript → suits → agent tasks',()=>window.__jarvisMeetingWork?.show()],['Product Studio','Photo → scene → video',()=>window.__jarvisProductStudio?.show()],['Needs my attention','Finished work and approvals',()=>window.__jarvisWorkbench?.show()],['Work desk','Proposals, files, photos and trophies',()=>window.__jarvisWorkDesk?.show()],['Agent Tower','Tasks and reviewed results',()=>window.__jarvisTower?.show()],['JARVIS Core','Conversations and approvals',()=>window.__jarvisCore?.show()],['Routines','Schedules, backups and travel',()=>window.__jarvisRoutines?.show()],['Think','Saved ideas',()=>window.__jarvisIdeas?.show()],['Move tabs to a screen','Connected screens and snapping',()=>window.__jarvisScreens?.show()],['What JARVIS can do','Feature guide',()=>window.__jarvisGuide?.show()],['Settings','Preferences and suits',()=>J.call('action',{action:'settings'})]];
 async function show(command='menu',id){if(opening)return;if(panel)await close();if(document.querySelector('.wb-panel,.jc,.wt-guide')){notice('Close the current panel to use the Work menu.');return;}opening=true;try{state=await J.call('workspace-list');mode=command;tabId=id||state.tabs.find(t=>t.active)?.id;if(mode!=='menu'&&!state.inside){notice('Open a suit to use its browser tabs.');return;}previous=document.activeElement;masked=await J.call('tabs-state').catch(()=>false);if(masked)await J.call('tabs-show',false);panel=document.createElement('section');panel.className='wb-panel wm-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',mode==='menu'?'Work menu':'Web address');panel.innerHTML=`<header><div><small>YOUR WORKSPACE</small><h2>${mode==='menu'?'Where do you want to work?':mode==='new'?'Open a new tab':'Go to a web address'}</h2></div><button data-close>Close</button></header><div class="wb-body"><form><label>${mode==='menu'?'Find a suit, tab or tool':'Website address'}<input type="${mode==='menu'?'search':'text'}" autocomplete="off" placeholder="${mode==='menu'?'Product Studio, Mark, proposal…':'https://example.com'}"></label>${mode!=='menu'?'<button>Open page</button>':''}</form><div class="wm-results"></div>${mode==='menu'?`<label class="wm-fast"><input type="checkbox" ${state.quick?'checked':''}> Shorten suit transitions while working</label>`:''}<p class="wm-help">Ctrl+K Work menu · Ctrl+L Address · Ctrl+T New tab · Ctrl+W Close tab · Ctrl+Shift+T Reopen · Ctrl+Tab Next tab</p><p class="wm-help">Switching suits restores saved page addresses. Save forms and unfinished web work before switching.</p></div>`;document.body.append(panel);const input=panel.querySelector('input');if(mode==='address')input.value=state.tabs.find(t=>t.id===tabId)?.url||'';panel.querySelector('[data-close]').onclick=close;panel.querySelector('form').onsubmit=e=>{e.preventDefault();go().catch(e=>notice(e.message));};input.oninput=()=>render(input.value);panel.querySelector('.wm-fast input')?.addEventListener('change',async e=>{const b=e.target;try{await J.call('settings',{quickWork:b.checked});state.quick=b.checked;}catch(err){b.checked=state.quick;notice(err.message);}});render('');input.focus();input.select();}catch(e){await close();notice(e.message);}finally{opening=false;}}
 function render(q){if(mode!=='menu')return;const all=[...state.tabs.map(t=>({label:t.title,detail:(t.popped?'Detached tab · ':'Open tab · ')+t.url,run:()=>J.call('tabs-activate',t.id)})),...tools.map(([label,detail,run])=>({label,detail,run})),...(state.inside?[{label:'Open a new tab',detail:'Ctrl+T',run:()=>show('new')},...(state.closed?[{label:'Reopen last closed tab',detail:'Ctrl+Shift+T',run:()=>J.call('workspace-shortcut',{command:'reopen'})}]:[])]:[]),...state.suits.map(s=>({label:s.name,detail:s.hall,run:()=>J.call('workspace-suit',{id:s.id,theme:s.theme})}))];rows=all.filter(r=>(r.label+' '+r.detail).toLowerCase().includes(q.toLowerCase())).slice(0,40);selected=0;const box=panel.querySelector('.wm-results');box.innerHTML=rows.map((r,i)=>`<button data-row="${i}" aria-selected="${i===selected}"><strong>${esc(r.label)}</strong><span>${esc(r.detail)}</span></button>`).join('')||'<p>No matches. Try a suit name or “Product Studio”.</p>';box.onclick=e=>{const b=e.target.closest('[data-row]');if(b){selected=Number(b.dataset.row);go().catch(e=>notice(e.message));}};}
 async function go(){if(!panel)return;if(mode==='menu'){const r=rows[selected];if(r){await close();await r.run();}}else{let url=panel.querySelector('input').value.trim();if(!/^\w+:/.test(url))url='https://'+url;const u=new URL(url);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw Error('Use a web address without passwords.');await J.call(mode==='new'||!tabId?'tabs-open':'tabs-address',{id:tabId,url:u.href});await close();}}
 const trigger=document.createElement('button');trigger.className='wm-trigger';trigger.innerHTML='Work <kbd>Ctrl+K</kbd>';trigger.setAttribute('aria-label','Open Work menu');trigger.onclick=()=>show();document.body.append(trigger);
 addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}if(mode==='menu'&&['ArrowDown','ArrowUp'].includes(e.key)&&rows.length){e.preventDefault();selected=(selected+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;panel.querySelectorAll('[data-row]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===selected)));panel.querySelector(`[data-row="${selected}"]`)?.scrollIntoView({block:'nearest'});}if(e.key==='Tab'){const a=[...panel.querySelectorAll('button,input')];if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus();}}},true);
 const off=J.on('core',m=>{if(m.type==='workspace-command'){if(m.command==='studio'){if(!document.querySelector('.wb-panel,.jc,.wt-guide'))window.__jarvisProductStudio?.show();else notice('Close the current panel, then open Product Studio from Work.');}else show(m.command,m.id);}if(m.type==='workspace-error')notice(m.message);});window.__jarvisWorkMenu={show,close};addEventListener('pagehide',()=>{off();trigger.remove();});
}
